  .fid.tr { top:14px; right:14px;  border-top:1px solid #a89f8d; border-right:1px solid #a89f8d; }
  .fid.bl { bottom:14px; left:14px;  border-bottom:1px solid #a89f8d; border-left:1px solid #a89f8d; }
