</head>
<body>

<canvas id="sky" role="img" aria-label="Animated spiral galaxy: hundreds of stars orbiting a bright glowing core, twinkling, with occasional supernovae. Click to trigger a supernova, scroll to zoom, move the pointer for parallax."></canvas>

<div class="fid tl"></div><div class="fid tr"></div><div class="fid bl"></div><div class="fid br"></div>

<header class="ui" id="plate">
  <h1>UGC 11437</h1>
  <p>SA(s)bc &middot; grand-design spiral &mdash; inclined plate, i &asymp; 37&deg;</p>
  <p id="meta">&mdash;</p>
</header>

<div class="ui" id="hint">click &mdash; supernova&ensp;&middot;&ensp;scroll &mdash; zoom&ensp;&middot;&ensp;move &mdash; parallax</div>

<div class="ui" id="tele"><span id="t">T+ 00:00</span><span class="sep">&middot;</span><span>SN <b id="sn">00</b></span><span class="sep">&middot;</span><span>Z <b id="z">1.00&times;</b></span></div>

<script>
(() => {
'use strict';

/* ---------------- canvas & global state ---------------- */
const cv  = document.getElementById('sky');
const ctx = cv.getContext('2d');
const TAU = Math.PI * 2;

let W = 0, H = 0, DPR = 1;
let K = 300;                 // pixels per galaxy unit (recomputed each frame)
let CX = 0, CY = 0;          // galaxy centre on screen
let CT = 1, ST_ = 0;         // plane-rotation cosine / sine
let ready = false;

const INCL   = 0.80;         // disk inclination (1 = face-on)
const PLANE  = -0.35;        // screen rotation of the major axis
const OMEGA0 = 0.06;         // base angular speed; differential rotation below
const omega  = r => OMEGA0 * (1 + 0.7 * Math.exp(-r * 3.0));

let simT = 0, lastNow = performance.now();
const motionScale = matchMedia('(prefers-reduced-motion: reduce)').matches ? 0.25 : 1;

let zoom = 1, zoomT = 1;
let px = 0, py = 0, pxT = 0, pyT = 0;

/* ---------------- helpers ---------------- */
const rnd   = (a, b) => a + Math.random() * (b - a);
const pick  = (...v) => v[(Math.random() * v.length) | 0];
const clamp = (v, a, b) => v < a ? a : v > b ? b : v;
const gauss = () => {
  let u = 0, v = 0;
  while (!u) u = Math.random();
  while (!v) v = Math.random();
  return Math.sqrt(-2 * Math.log(u)) * Math.cos(TAU * v);
};
const hexRGB = h => [parseInt(h.slice(1, 3), 16), parseInt(h.slice(3, 5), 16), parseInt(h.slice(5, 7), 16)];

/* ---------------- pre-rendered light sprites (no per-frame gradients) ---------------- */
function glowSprite(hex) {
  const c = document.createElement('canvas'); c.width = c.height = 64;
  const g = c.getContext('2d'), [r, gr, b] = hexRGB(hex);
  const rad = g.createRadialGradient(32, 32, 0, 32, 32, 32);
  rad.addColorStop(0.00, 'rgba(255,255,255,1)');
  rad.addColorStop(0.10, 'rgba(255,255,255,0.85)');
  rad.addColorStop(0.24, `rgba(${r},${gr},${b},0.55)`);
  rad.addColorStop(0.52, `rgba(${r},${gr},${b},0.13)`);
  rad.addColorStop(1.00, `rgba(${r},${gr},${b},0)`);
  g.fillStyle = rad; g.fillRect(0, 0, 64, 64);
  return c;
}
function blobSprite(hex) {
  const c = document.createElement('canvas'); c.width = c.height = 128;
  const g = c.getContext('2d'), [r, gr, b] = hexRGB(hex);
  const rad = g.createRadialGradient(64, 64, 0, 64, 64, 64);
  rad.addColorStop(0.0, `rgba(${r},${gr},${b},0.50)`);
  rad.addColorStop(0.4, `rgba(${r},${gr},${b},0.16)`);
  rad.addColorStop(1.0, `rgba(${r},${gr},${b},0)`);
  g.fillStyle = rad; g.fillRect(0, 0, 128, 128);
  return c;
}
/* stellar palette: white, cool whites, blues, warm whites, amber, HII pink */
const SPR  = ['#ffffff','#f5f7ff','#cfe0ff','#a9c4ff','#8fb0ff','#ffedc4','#ffd9a1','#ffb083','#ff9fb8'].map(glowSprite);
const BLOB = ['#4c6fc4','#6f93da','#a5bdea','#d9a05c'].map(blobSprite);

const CORE = (() => {
  const c = document.createElement('canvas'); c.width = c.height = 256;
  const g = c.getContext('2d');
  const rad = g.createRadialGradient(128, 128, 0, 128, 128, 128);
  rad.addColorStop(0.00, 'rgba(255,255,255,1)');
  rad.addColorStop(0.05, 'rgba(255,250,238,0.95)');
  rad.addColorStop(0.16, 'rgba(255,231,178,0.50)');
  rad.addColorStop(0.38, 'rgba(255,203,122,0.16)');
  rad.addColorStop(0.68, 'rgba(214,142,74,0.05)');
  rad.addColorStop(1.00, 'rgba(214,142,74,0)');
  g.fillStyle = rad; g.fillRect(0, 0, 256, 256);
  return c;
})();

/* diffraction-spike spindle (deep-field style), reused for core + bright giants */
const SPK = (() => {
  const c = document.createElement('canvas'); c.width = 512; c.height = 48;
  const g = c.getContext('2d');
  const gx = g.createLinearGradient(0, 0, 512, 0);
  gx.addColorStop(0, 'rgba(255,244,224,0)');
  gx.addColorStop(0.5, 'rgba(255,244,224,1)');
  gx.addColorStop(1, 'rgba(255,244,224,0)');
  g.fillStyle = gx; g.fillRect(0, 0, 512, 48);
  const gy = g.createLinearGradient(0, 0, 0, 48);
  gy.addColorStop(0, 'rgba(0,0,0,0)');
  gy.addColorStop(0.5, 'rgba(0,0,0,1)');
  gy.addColorStop(1, 'rgba(0,0,0,0)');
  g.globalCompositeOperation = 'destination-in';
  g.fillStyle = gy; g.fillRect(0, 0, 512, 48);
  return c;
})();

/* ---------------- galaxy: two log-spiral arms + bulge + field + haze ---------------- */
const stars = [], hazes = [], armList = [];
const ARMS = 2, R0 = 0.055, WIND = 1.4 * TAU;
const KK = Math.log(1 / R0) / WIND;                 // log-spiral pitch
const clusterU = [[], []];                          // OB-association knots along each arm
for (let a = 0; a < ARMS; a++)
  for (let i = 0; i < 24; i++) clusterU[a].push(Math.pow(Math.random(), 0.78));

function armPoint(arm, u, dTheta, dRad, w) {
  const th = arm * TAU / ARMS + u * WIND + gauss() * dTheta;
  const r  = R0 * Math.exp(KK * u * WIND) * (1 + gauss() * dRad);
  return [r * Math.cos(th) + gauss() * w, r * Math.sin(th) + gauss() * w];
}
function pushStar(x, y, c, s, a0, glint) {
  const r = Math.hypot(x, y);
  stars.push({
    r, th0: Math.atan2(y, x), w: omega(r), c, s, a0, glint: !!glint,
    amp: clamp(1.15 - s * 20, 0.3, 0.95),           // small stars scintillate more
    f1: rnd(2.5, 7.5), f2: rnd(0.5, 1.4),           // fast shimmer + slow swell
    p1: rnd(0, TAU), p2: rnd(0, TAU)
  });
  return stars.length - 1;
}

/* arm stars, clumped into star-forming associations */
for (let arm = 0; arm < ARMS; arm++)
  for (let i = 0; i < 360; i++) {
    const cu = clusterU[arm];
    let u, fromC = false;
    if (Math.random() < 0.5) { u = cu[(Math.random() * cu.length) | 0] + gauss() * 0.02; fromC = true; }
    else u = Math.pow(Math.random(), 0.72);
    u = clamp(u, 0, 1);
    const [x, y] = armPoint(arm, u, 0.05 + 0.26 * Math.pow(u, 1.6), 0.04, 0.010 + 0.085 * u);
    const roll = Math.random();
    let c, s, a0;
    if (fromC && roll < 0.09)                        { c = 8; s = rnd(0.018, 0.032); a0 = rnd(0.7, 0.95); } // pink HII knots
    else if (roll < (fromC ? 0.60 : 0.26) + 0.4 * u) { c = pick(2, 3, 2, 3, 4); s = rnd(0.012, 0.030); a0 = rnd(0.65, 0.95); } // young blue stars
    else if (roll > 0.965)                           { c = 7; s = rnd(0.022, 0.038); a0 = rnd(0.7, 0.9);  } // amber giants
    else                                             { c = pick(0, 1, 5, 1, 6); s = rnd(0.010, 0.022); a0 = rnd(0.5, 0.85); }
    armList.push(pushStar(x, y, c, s, a0));
  }

/* a few luminous beacons that anchor the arms */
for (let i = 0; i < 10; i++) {
  const arm = (Math.random() * ARMS) | 0, u = rnd(0.3, 0.95);
  const [x, y] = armPoint(arm, u, 0.05, 0.03, 0.02);
  armList.push(pushStar(x, y, pick(2, 3, 0), rnd(0.042, 0.058), 0.95, true));
}

/* central bulge — old, warm population */
for (let i = 0; i < 180; i++) {
  const r = Math.min(0.30, Math.abs(gauss()) * 0.075 + 0.004), th = rnd(0, TAU);
  pushStar(r * Math.cos(th), r * Math.sin(th), pick(5, 5, 6, 0, 1),
           rnd(0.008, 0.02), 0.5 + 0.45 * (1 - r / 0.3));
}

/* scattered disk field */
for (let i = 0; i < 230; i++) {
  const r = 0.10 + 0.92 * Math.pow(Math.random(), 0.85), th = rnd(0, TAU);
  pushStar(r * Math.cos(th), r * Math.sin(th), pick(1, 5, 6, 2), rnd(0.007, 0.015), rnd(0.28, 0.55));
}

/* luminous haze riding the exact same rotation field as the stars */
for (let arm = 0; arm < ARMS; arm++)
  for (let i = 0; i < 55; i++) {
    const cu = clusterU[arm];
    let u;
    if (Math.random() < 0.6) u = clamp(cu[(Math.random() * cu.length) | 0] + gauss() * 0.03, 0, 1);
    else u = Math.pow(Math.random(), 0.7);
    const [x, y] = armPoint(arm, u, 0.06 + 0.3 * u, 0.05, 0.02 + 0.12 * u);
    const r = Math.hypot(x, y);
    hazes.push({ r, th0: Math.atan2(y, x), w: omega(r),
                 c: r < 0.24 ? 3 : pick(0, 1, 1, 2),
                 s: rnd(0.05, 0.13) * (0.7 + 0.6 * u), a: rnd(0.05, 0.11) });
  }
for (let i = 0; i < 16; i++) {                        // warm inner-disk haze
  const r = rnd(0.04, 0.26), th = rnd(0, TAU);
  hazes.push({ r, th0: th, w: omega(r), c: 3, s: rnd(0.06, 0.12), a: rnd(0.05, 0.09) });
}
for (let i = 0; i < 14; i++) {                        // faint outer ambience
  const r = rnd(0.7, 1.15), th = rnd(0, TAU);
  hazes.push({ r, th0: th, w: omega(r), c: pick(0, 1), s: rnd(0.12, 0.2), a: rnd(0.03, 0.06) });
}

const sx = new Float32Array(stars.length), sy = new Float32Array(stars.length);

/* ---------------- supernovae ---------------- */
const SNe = [];
let snCount = 0, nextSN = 5 + Math.random() * 5;
function spawnSN(r, angNow) {
  if (SNe.length > 12) return;
  SNe.push({ r, th0: angNow - omega(r) * simT, w: omega(r), t0: simT, dur: rnd(2.1, 3.3) });
  snCount++;
}

/* ---------------- deep-field backdrop (pre-rendered once) ---------------- */
let back = null, tfar = [];
function buildBackdrop() {
  back = document.createElement('canvas');
  back.width = Math.max(1, Math.round(W * DPR));
  back.height = Math.max(1, Math.round(H * DPR));
  const g = back.getContext('2d');
  g.setTransform(DPR, 0, 0, DPR, 0, 0);
  const n = Math.round(W * H / 9000);
  for (let i = 0; i < n; i++) {
    const a = 0.05 + Math.pow(Math.random(), 2.2) * 0.5;
    const t = Math.random();
    g.fillStyle = t < 0.72 ? `rgba(220,226,238,${a})`
                : t < 0.90 ? `rgba(255,236,210,${a})`
                :            `rgba(190,208,255,${a})`;
    g.beginPath();
    g.arc(Math.random() * W, Math.random() * H, 0.4 + Math.pow(Math.random(), 2) * 0.9, 0, TAU);
    g.fill();
  }
  tfar = [];
  for (let i = 0; i < 26; i++)
    tfar.push({ x: Math.random() * W, y: Math.random() * H,
                r: 0.5 + Math.random() * 0.8, a: 0.25 + Math.random() * 0.45,
                f: rnd(0.4, 1.8), p: rnd(0, TAU) });
}

function resize() {
  W = innerWidth; H = innerHeight;
  DPR = Math.min(devicePixelRatio || 1, 1.75);
  cv.width = Math.round(W * DPR); cv.height = Math.round(H * DPR);
  cv.style.width = W + 'px'; cv.style.height = H + 'px';
  buildBackdrop();
}
addEventListener('resize', resize);
resize();

/* ---------------- interaction ---------------- */
addEventListener('pointermove', e => {
  pxT = (e.clientX / W) * 2 - 1;
  pyT = (e.clientY / H) * 2 - 1;
});
addEventListener('pointerdown', e => {
  const mx = e.clientX, my = e.clientY;
  if (ready) {                                        // snap to the nearest star if one is close
    let best = -1, bd = Math.pow(Math.max(46, K * 0.05), 2);
    for (let i = 0; i < stars.length; i++) {
      const dx = sx[i] - mx, dy = sy[i] - my, d = dx * dx + dy * dy;
      if (d < bd) { bd = d; best = i; }
    }
    if (best >= 0) { const s = stars[best]; spawnSN(s.r, s.th0 + s.w * simT); return; }
  }
  const ux = (mx - CX) / K, uy = (my - CY) / K;       // else invert the plate transform
  const gx = ux * CT + uy * ST_, gy = (-ux * ST_ + uy * CT) / INCL;
  const r = Math.hypot(gx, gy);
  if (r < 1.5) spawnSN(r, Math.atan2(gy, gx));
});
addEventListener('wheel', e => {
  e.preventDefault();
  zoomT = clamp(zoomT * (e.deltaY > 0 ? 0.9 : 1.1), 0.55, 1.9);
}, { passive: false });

/* ---------------- telemetry ---------------- */
const tEl = document.getElementById('t'),
      nEl = document.getElementById('sn'),
      zEl = document.getElementById('z');
document.getElementById('meta').textContent =
  String(stars.length + hazes.length).replace(/\B(?=(\d{3})+(?!\d))/g, '\u2009') + ' resolved sources \u00b7 live render';
const fmtT = t => String((t / 60) | 0).padStart(2, '0') + ':' + String((t % 60) | 0).padStart(2, '0');
let lastUI = 0;

/* ---------------- frame loop ---------------- */
function frame(now) {
  requestAnimationFrame(frame);
  let dt = (now - lastNow) / 1000; lastNow = now;
  if (dt > 0.1) dt = 0.1;
  simT += dt * motionScale;

  zoom += (zoomT - zoom) * Math.min(1, dt * 4.5);
  px += (pxT - px) * Math.min(1, dt * 3);
  py += (pyT - py) * Math.min(1, dt * 3);

  const introE = 1 - Math.pow(1 - Math.min(simT / 2.6, 1), 3);   // opening settle
  const mA = introE;
  K = Math.min(W, H) * 0.44 * zoom * (1 + 0.28 * Math.pow(1 - introE, 2));
  CX = W / 2 - px * 30; CY = H / 2 - py * 22;
  CT = Math.cos(PLANE); ST_ = Math.sin(PLANE);

  ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
  ctx.globalCompositeOperation = 'source-over';
  ctx.globalAlpha = 1;
  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, W, H);

  /* distant field */
  ctx.globalAlpha = 0.9;
  ctx.drawImage(back, -px * 12, -py * 9, W, H);
  ctx.fillStyle = '#d8dee9';
  for (let i = 0; i < tfar.length; i++) {
    const f = tfar[i];
    ctx.globalAlpha = f.a * (0.35 + 0.65 * (0.5 + 0.5 * Math.sin(simT * f.f + f.p)));
    ctx.beginPath(); ctx.arc(f.x, f.y, f.r, 0, TAU); ctx.fill();
  }

  ctx.globalCompositeOperation = 'lighter';
  const ct = CT, st_ = ST_;

  /* nebular haze — same orbital motion as the stars */
  for (let i = 0; i < hazes.length; i++) {
    const h = hazes[i], a = h.th0 + h.w * simT;
    const gx = h.r * Math.cos(a), gy = h.r * Math.sin(a) * INCL;
    const X = CX + (gx * ct - gy * st_) * K, Y = CY + (gx * st_ + gy * ct) * K;
    const s = h.s * K * 2;
    ctx.globalAlpha = h.a * mA;
    ctx.drawImage(BLOB[h.c], X - s / 2, Y - s / 2, s, s);
  }

  /* stars */
  for (let i = 0; i < stars.length; i++) {
    const s = stars[i], a = s.th0 + s.w * simT, sa = Math.sin(a);
    const gx = s.r * Math.cos(a), gy = s.r * sa * INCL;
    const X = CX + (gx * ct - gy * st_) * K, Y = CY + (gx * st_ + gy * ct) * K;
    sx[i] = X; sy[i] = Y;
    const depth = 1 + 0.14 * sa;                      // near edge of the tilted disk reads closer
    const tw = 0.74 + 0.26 * Math.sin(simT * s.f1 + s.p1) * s.amp
                   + 0.16 * Math.sin(simT * s.f2 + s.p2);
    let al = s.a0 * tw * depth * mA;
    if (al < 0.015) al = 0.015;
    if (al > 1) al = 1;
    ctx.globalAlpha = al;
    const sz = s.s * K * depth;
    ctx.drawImage(SPR[s.c], X - sz / 2, Y - sz / 2, sz, sz);
    if (s.glint) {                                    // faint spikes on the brightest giants
      const gl = sz * 2.6, gh = gl * 0.07;
      ctx.globalAlpha = al * 0.4;
      ctx.drawImage(SPK, X - gl / 2, Y - gh / 2, gl, gh);
      ctx.save(); ctx.translate(X, Y); ctx.rotate(Math.PI / 2);
      ctx.drawImage(SPK, -gl / 2, -gh / 2, gl, gh); ctx.restore();
    }
  }

  /* core + breathing diffraction spikes */
  const pulse = 1 + 0.03 * Math.sin(simT * 0.7) + 0.016 * Math.sin(simT * 1.83 + 1.7);
  const cs = K * 0.36 * pulse;
  ctx.globalAlpha = 0.9 * mA;
  ctx.drawImage(CORE, CX - cs / 2, CY - cs / 2, cs, cs);
  const spL = K * 0.92 * pulse, spW = spL * 0.075;
  ctx.globalAlpha = clamp(0.30 + 0.12 * Math.sin(simT * 0.43) + 0.05 * Math.sin(simT * 1.31), 0.08, 0.55) * mA;
  ctx.drawImage(SPK, CX - spL / 2, CY - spW / 2, spL, spW);
  ctx.save(); ctx.translate(CX, CY); ctx.rotate(Math.PI / 2);
  ctx.drawImage(SPK, -spL / 2, -spW / 2, spL, spW); ctx.restore();

  /* supernovae: flash + expanding light ring, orbiting with the galaxy */
  for (let i = SNe.length - 1; i >= 0; i--) {
    const s = SNe[i], e = (simT - s.t0) / s.dur;
    if (e >= 1) { SNe.splice(i, 1); continue; }
    const a = s.th0 + s.w * simT;
    const gx = s.r * Math.cos(a), gy = s.r * Math.sin(a) * INCL;
    const X = CX + (gx * ct - gy * st_) * K, Y = CY + (gx * st_ + gy * ct) * K;
    const eo = 1 - Math.pow(1 - e, 3);
    const fa = e < 0.1 ? e / 0.1 : Math.pow(1 - (e - 0.1) / 0.9, 2.2);
    const fs = K * (0.04 + 0.34 * eo);
    ctx.globalAlpha = clamp(fa, 0, 1) * 0.95 * mA;
    ctx.drawImage(SPR[1], X - fs / 2, Y - fs / 2, fs, fs);
    ctx.globalAlpha = Math.pow(1 - e, 1.7) * 0.5 * mA;
    ctx.strokeStyle = 'rgba(255,232,205,1)';
    ctx.lineWidth = Math.max(0.7, (1 - e) * 2.6);
    ctx.beginPath();
    ctx.arc(X, Y, K * 0.015 + K * 0.30 * eo, 0, TAU);
    ctx.stroke();
  }

  ready = true;

  /* the sky occasionally detonates on its own */
  if (simT > nextSN) {
    const s = stars[armList[(Math.random() * armList.length) | 0]];
    spawnSN(s.r, s.th0 + s.w * simT);
    nextSN = simT + 6.5 + Math.random() * 8;
  }

  if (now - lastUI > 240) {
    lastUI = now;
    tEl.textContent = 'T+ ' + fmtT(simT);
    nEl.textContent = String(snCount).padStart(2, '0');
    zEl.textContent = zoom.toFixed(2) + '\u00d7';
  }
}
requestAnimationFrame(frame);
})();
